// tb.v: random-stimulus testbench for Arith, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg [7:0] a = 8'd0;
    reg [7:0] b = 8'd0;
    reg [7:0] sa = 8'd0;
    reg [7:0] sb = 8'd0;
    reg [3:0] sh = 4'd0;
    reg c = 1'b0;
    reg [99:0] w1 = 100'd0;
    reg [99:0] w2 = 100'd0;
    wire [7:0] add;
    wire [7:0] sub;
    wire [7:0] mul;
    wire [7:0] smul;
    wire [7:0] udiv;
    wire [7:0] umod;
    wire [7:0] sdiv;
    wire [7:0] smod;
    wire [7:0] divc;
    wire [7:0] modc;
    wire [7:0] sdivc;
    wire [7:0] smodc;
    wire ult;
    wire ule;
    wire slt;
    wire sge;
    wire sgt_u;
    wire sltk;
    wire [7:0] shl;
    wire [7:0] shr;
    wire [7:0] ashr;
    wire [7:0] shr_s;
    wire [7:0] shl_far;
    wire [7:0] neg;
    wire [7:0] inv;
    wire rand_;
    wire ror;
    wire rxor;
    wire logic_;
    wire [7:0] mix1;
    wire [7:0] mix2;
    wire [7:0] mix3;
    wire mix4;
    wire [7:0] mix5;
    wire [15:0] mix6;
    wire mix7;
    wire [7:0] mix8;
    wire [7:0] mix9;
    wire mix10;
    wire [99:0] wadd;
    wire [99:0] wmul;
    wire [99:0] wxor;
    wire [99:0] wshr;
    wire [99:0] washr;
    wire wlt;
    wire [99:0] wdiv;
    wire [99:0] wsdiv;
    reg [236:0] stim [0:239];
    integer i;

    Arith dut (
        .a(a),
        .b(b),
        .sa(sa),
        .sb(sb),
        .sh(sh),
        .c(c),
        .w1(w1),
        .w2(w2),
        .add(add),
        .sub(sub),
        .mul(mul),
        .smul(smul),
        .udiv(udiv),
        .umod(umod),
        .sdiv(sdiv),
        .smod(smod),
        .divc(divc),
        .modc(modc),
        .sdivc(sdivc),
        .smodc(smodc),
        .ult(ult),
        .ule(ule),
        .slt(slt),
        .sge(sge),
        .sgt_u(sgt_u),
        .sltk(sltk),
        .shl(shl),
        .shr(shr),
        .ashr(ashr),
        .shr_s(shr_s),
        .shl_far(shl_far),
        .neg(neg),
        .inv(inv),
        .rand_(rand_),
        .ror(ror),
        .rxor(rxor),
        .logic_(logic_),
        .mix1(mix1),
        .mix2(mix2),
        .mix3(mix3),
        .mix4(mix4),
        .mix5(mix5),
        .mix6(mix6),
        .mix7(mix7),
        .mix8(mix8),
        .mix9(mix9),
        .mix10(mix10),
        .wadd(wadd),
        .wmul(wmul),
        .wxor(wxor),
        .wshr(wshr),
        .washr(washr),
        .wlt(wlt),
        .wdiv(wdiv),
        .wsdiv(wsdiv)
    );

    task do_reset;
        begin
            #1;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {a, b, sa, sb, sh, c, w1, w2} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h", i, add, sub, mul, smul, udiv, umod, sdiv, smod, divc, modc, sdivc, smodc, ult, ule, slt, sge, sgt_u, sltk, shl, shr, ashr, shr_s, shl_far, neg, inv, rand_, ror, rxor, logic_, mix1, mix2, mix3, mix4, mix5, mix6, mix7, mix8, mix9, mix10, wadd, wmul, wxor, wshr, washr, wlt, wdiv, wsdiv);
            #9;
        end
        $finish;
    end
endmodule
